def regions(g,v):
    R,C=len(g),len(g[0]); seen=set(); regs=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]==v and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<R and 0<=nb<C and g[na][nb]==v and (na,nb) not in seen:
                            seen.add((na,nb)); st.append((na,nb))
                regs.append(comp)
    return regs
